import{_ as l,l as i,o as e,c as s,v as t,p as d,x as o,d as n,i as c,S as h}from"./chunks/framework.InCnrqk-.js";const m=JSON.parse('{"title":"影子栈与 CET","description":"","frontmatter":{"title":"影子栈与 CET","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/shadow-stack-cet.md","filePath":"cs/shadow-stack-cet.md","lastUpdated":1789023840000}'),E={name:"cs/shadow-stack-cet.md"};function p(T,a,B,_,A,C){const r=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="影子栈与-cet" tabindex="-1">影子栈与 CET <a class="header-anchor" href="#影子栈与-cet" aria-label="Permalink to &quot;影子栈与 CET&quot;">​</a></h1><div class="epigraph"><p>影子栈把返回地址放进攻击者默认不可写的第二份栈；CET 再给间接跳加「合法目标」标记。硬件把 CFI 从编译器希望变成页表与指令集合同。</p><footer>—— Intel CET 白皮书；对照 Abadi CFI；Microsoft 对 HW-enforced stack protection 的陈述</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/type-confusion">类型混淆</a>仍可能改函数指针。缺口是<strong>硬件协助的控制流</strong>：影子栈与 IBT。不重写 ROP 定义，只补不能单靠软件希望。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>软件 CFI 可被同进程任意写削弱。影子栈：<code>call</code> 压两份，<code>ret</code> 核对。IBT：间接跳只落到 <code>endbr</code> 一类着陆点。缺口是覆盖率（哪些库编译进去）与兼容。</p><h3 id="不是内存安全" tabindex="-1">不是内存安全 <a class="header-anchor" href="#不是内存安全" aria-label="Permalink to &quot;不是内存安全&quot;">​</a></h3><p>数据面仍可改。只是返回与部分间接边变贵。</p><p><span class="marginnote">Intel CET。ARM 有 PAC（下一课）与 BTI。本课不写绕过 CET 的步骤。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照软件影子栈与硬件。指出 JIT 要发着陆指令。与 ASLR 叠加。下一课 PAC：签指针本身。</p>',12)),(e(),d(h,null,{default:o(()=>[c(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20CALL%5B%22call%22%5D%20--%3E%20SS%5B%22%E5%BD%B1%E5%AD%90%E6%A0%88%E5%AD%98%E8%BF%94%E5%9B%9E%E5%9C%B0%E5%9D%80%22%5D%0A%20%20RET%5B%22ret%22%5D%20--%3E%20CMP%5B%22%E4%B8%8E%E5%BD%B1%E5%AD%90%E6%A0%88%E6%A0%B8%E5%AF%B9%22%5D%0A%20%20IJ%5B%22%E9%97%B4%E6%8E%A5%E8%B7%B3%22%5D%20--%3E%20ENDBR%5B%22%E9%A1%BB%E8%90%BD%E5%88%B0%E5%90%88%E6%B3%95%E7%9D%80%E9%99%86%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>控制边被硬件当一等对象。下一课指针认证：把签名放进指针高位，改指针要过密钥。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不给关闭 CET 的利用。PAC 下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>类型混淆仍要改控制数据；CET 让返回/间接跳变硬。</li><li>影子栈核对返回；IBT 限制着陆点。</li><li>覆盖率取决于编译与 JIT。</li><li>下一课指针认证 PAC。</li><li>出处：Intel CET；Abadi et al.；对照 ARM BTI。</li></ul>',8))])}const f=l(E,[["render",p]]);export{m as __pageData,f as default};
